<?php $user=currentUser();$balance=getBonusBalance($user['id']);$history=getBonusHistory($user['id']);$tasks=function_exists('getActiveTasks')?getActiveTasks():[];$pageTitle='Бонусы покупателя';include __DIR__.'/../templates/header.php'; ?>
<a href="/profile" class="btn btn-secondary" style="margin-bottom:16px">← Профиль</a><h1 style="font-size:22px;font-weight:700;margin-bottom:8px">🎁 Бонусы покупателя</h1><p style="color:var(--g-text-secondary);font-size:14px;line-height:1.6;margin-bottom:20px"><strong>10 бонусов = 5% скидки</strong> на следующий заказ. Бонусы можно копить и использовать частично.</p><div class="card" style="padding:28px;text-align:center;margin-bottom:24px"><div style="color:var(--g-text-secondary);font-size:13px">Ваш баланс</div><div style="font-size:40px;font-weight:800;color:var(--g-accent-light)"><?=$balance?></div><div style="font-size:12px;color:var(--g-text-secondary)">Максимум скидки задаётся администрацией.</div></div><h2 style="font-size:17px;font-weight:600;margin-bottom:12px">Задания от администрации</h2><?php if(!$tasks):?><p style="color:var(--g-text-secondary);margin-bottom:20px">Активных заданий пока нет.</p><?php else:?><div style="display:grid;gap:10px;margin-bottom:24px"><?php foreach($tasks as $t):?><div class="card" style="padding:16px"><strong><?=e($t['title'])?></strong><span style="color:var(--g-accent-light);margin-left:8px">+<?=e($t['bonus_amount'])?> бонусов</span><?php if($t['description']):?><div style="font-size:13px;color:var(--g-text-secondary);margin-top:5px"><?=e($t['description'])?></div><?php endif;?></div><?php endforeach;?></div><?php endif;?>
<h2 style="font-size:17px;font-weight:600;margin-bottom:12px">Как получить бонусы</h2><div style="display:grid;gap:10px;margin-bottom:24px"><div class="card" style="padding:16px">🛒 Совершайте покупки — бонусы начисляются за подходящие заказы.</div><div class="card" style="padding:16px">🎯 Следите за заданиями и акциями, которые публикует администрация.</div></div><h2 style="font-size:17px;font-weight:600;margin-bottom:12px">История</h2><?php if(!$history):?><p style="color:var(--g-text-secondary)">Операций пока нет.</p><?php else:?><div style="overflow:auto"><table class="admin-table"><thead><tr><th>Дата</th><th>Сумма</th><th>Описание</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=date('d.m.Y H:i',strtotime($h['created_at']))?></td><td style="color:<?=$h['amount']>=0?'#34c759':'#ff3b30'?>"><?=($h['amount']>=0?'+':'').$h['amount']?></td><td><?=e($h['description'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php include __DIR__.'/../templates/footer.php'; ?>
